mapper.select:
SELECT pr.*,
       s.name AS studentName,
       s.class_id AS classId,
       c.class_name AS className,
       se.semester_name AS semesterName,
       ft.type_name AS feeTypeName,
       ft.type_code AS typeCode
FROM payment_record pr
LEFT JOIN student s ON pr.student_id = s.id
LEFT JOIN class_info c ON s.class_id = c.id
LEFT JOIN semester se ON pr.semester_id = se.id
LEFT JOIN fee_type ft ON pr.fee_type_id = ft.id


        AND pr.student_id = #{query.studentId}


        AND s.name LIKE CONCAT('%', #{query.studentName}, '%')


        AND s.class_id = #{query.classId}


        AND pr.semester_id = #{query.semesterId}


        AND pr.fee_type_id = #{query.feeTypeId}


        AND pr.pay_date >= #{query.payDateFrom}


        AND pr.pay_date <= #{query.payDateTo}


        AND pr.receipt_status = #{query.receiptStatus}


ORDER BY pr.id DESC
